window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-07a2ea8ce593aa52"]={"versions": [{"id": "FIG-07a2ea8ce593aa52", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Berechnungsdiagramm zur Alive-Supervision (Szenario B) im AUTOSAR Watchdog Manager (Wdm / WdgM). Das Diagramm stellt das Zusammenspiel zwischen periodischen Überwachungszyklen (<code>supervision cycle</code>, SC) und asynchronen Alive-Indikationen (AI) einer überwachten Entität (<code>Supervised Entity</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Zählersignale</strong>:</li>\n<li><code>AI</code> (Alive Indication): Ereignisimpulse (grüne Balken) der überwachten Software-Entität; ein ausbleibender Impuls ist rot gestrichelt hervorgehoben.</li>\n<li><code>SC</code> (Supervision Cycle): Diskrete Taktzyklen des Watchdog Managers (SC 1 bis SC 7, ...).</li>\n<li><code>n(AI)</code>: Interner Zähler für empfangene Alive Indications (grüner Signalverlauf).</li>\n<li><code>n(SC)</code>: Interner Zähler für abgelaufene Überwachungszyklen (schwarzer Signalverlauf).</li>\n<li><strong>Konfigurationsparameter & Formelgrößen</strong>:</li>\n<li><code>supervision reference cycle</code>: Referenzzykluslänge (hier 2 SC).</li>\n<li><code>expected n(SC)</code>: Erwartete Anzahl von Überwachungszyklen, bis eine Alive Indication eintreffen muss (hier 2).</li>\n<li><code>EAI</code>: Erwarteter Korrekturwert, definiert als <code>expected n(SC) - 1 = 1</code>.</li>\n<li><code>MinMargin = MaxMargin = 0</code>: Toleranzbereich um den Sollwert 0.</li>\n<li><strong>Zustandsleiste</strong>:</li>\n<li><code>continuous aliveness</code> (grün)</li>\n<li><code>corrupted aliveness</code> (orange)</li>\n<li><code>recovering aliveness</code> (hellgrün)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Normalbetrieb (SC 1 bis SC 3)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Alive Indication trifft innerhalb des Referenzintervalls ein.</li>\n<li>Beim Prüfzeitpunkt (rosa Pfeil unten, <code>perform check of alive counter</code>) wird die Bewertungsformel ausgewertet:</li>\n<li><code>CYCLE 1</code>: $n(AI) - n(SC) + EAI = 1 - 2 + 1 = 0 \\rightarrow$ <strong>o.k.</strong></li>\n<li><code>CYCLE 3</code>: $n(AI) - n(SC) + EAI = 1 - 2 + 1 = 0 \\rightarrow$ <strong>o.k.</strong></li>\n<li>Durch das Eintreffen der Alive Indication bzw. nach der Auswertung werden Überwachungs- und Alive-Zähler zurückgesetzt (blauer Pfeil nach oben).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerfall (SC 4 bis SC 5)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die erwartete Alive Indication bleibt aus (rot gestrichelter Balken).</li>\n<li>Beim Prüfzeitpunkt an SC 5 ergibt die Formel:</li>\n<li><code>CYCLE 5</code>: $n(AI) - n(SC) + EAI = 0 - 2 + 1 = -1 \\rightarrow$ <strong>not o.k.</strong></li>\n<li>Der Zustand wechselt zu <code>corrupted aliveness</code>.</li>\n<li>Ein Zähler-Reset erfolgt bedingt durch die erkannte Korruption (<code>caused by detected corruption</code>, roter Pfeil nach oben).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erholung (SC 6 bis SC 7)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Erreichen von SC 7 wird mit angepassten Zählerwerten geprüft:</li>\n<li><code>CYCLE 7</code>: $n(AI) - n(SC) + EAI = 0 - 1 + 1 = 0 \\rightarrow$ <strong>o.k.</strong></li>\n<li>Der Überwachungsstatus geht über <code>recovering aliveness</code> zurück in <code>continuous aliveness</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Algorithmus-Validierung</strong>: Das Szenario demonstriert eine Variante des Alive-Supervision-Algorithmus mit Zähler-Reset bei Alive-Indikation und bei erkannter Abweichung.</li>\n<li><strong>Toleranzgrenzen</strong>: Da <code>MinMargin = MaxMargin = 0</code>, führt jede Abweichung vom Ergebnis 0 unmittelbar zur Bewertung <code>not o.k.</code>.</li>\n<li><strong>EAI-Kompensation</strong>: Der Term <code>EAI = expected n(SC) - 1</code> dient als mathematischer Ausgleich für die Phasenverschiebung zwischen diskreten Überwachungszyklen und asynchronen Alive-Ereignissen.</li>\n</ul>"}, {"id": "FIG-15041c8a42ebc98c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Berechnungsdiagramm zur Alive-Supervision (Szenario B) im AUTOSAR Watchdog Manager (Wdm / WdgM). Das Diagramm stellt das Zusammenspiel zwischen periodischen Überwachungszyklen (<code>supervision cycle</code>, SC) und asynchronen Alive-Indikationen (AI) einer überwachten Entität (<code>Supervised Entity</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Zählersignale</strong>:</li>\n<li><code>AI</code> (Alive Indication): Ereignisimpulse (grüne Balken) der überwachten Software-Entität; ein ausbleibender Impuls ist rot gestrichelt hervorgehoben.</li>\n<li><code>SC</code> (Supervision Cycle): Diskrete Taktzyklen des Watchdog Managers (SC 1 bis SC 7, ...).</li>\n<li><code>n(AI)</code>: Interner Zähler für empfangene Alive Indications (grüner Signalverlauf).</li>\n<li><code>n(SC)</code>: Interner Zähler für abgelaufene Überwachungszyklen (schwarzer Signalverlauf).</li>\n<li><strong>Konfigurationsparameter & Formelgrößen</strong>:</li>\n<li><code>supervision reference cycle</code>: Referenzzykluslänge (hier 2 SC).</li>\n<li><code>expected n(SC)</code>: Erwartete Anzahl von Überwachungszyklen, bis eine Alive Indication eintreffen muss (hier 2).</li>\n<li><code>EAI</code>: Erwarteter Korrekturwert, definiert als <code>expected n(SC) - 1 = 1</code>.</li>\n<li><code>MinMargin = MaxMargin = 0</code>: Toleranzbereich um den Sollwert 0.</li>\n<li><strong>Zustandsleiste</strong>:</li>\n<li><code>continuous aliveness</code> (grün)</li>\n<li><code>corrupted aliveness</code> (orange)</li>\n<li><code>recovering aliveness</code> (hellgrün)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Normalbetrieb (SC 1 bis SC 3)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Alive Indication trifft innerhalb des Referenzintervalls ein.</li>\n<li>Beim Prüfzeitpunkt (rosa Pfeil unten, <code>perform check of alive counter</code>) wird die Bewertungsformel ausgewertet:</li>\n<li><code>CYCLE 1</code>: $n(AI) - n(SC) + EAI = 1 - 2 + 1 = 0 \\rightarrow$ <strong>o.k.</strong></li>\n<li><code>CYCLE 3</code>: $n(AI) - n(SC) + EAI = 1 - 2 + 1 = 0 \\rightarrow$ <strong>o.k.</strong></li>\n<li>Durch das Eintreffen der Alive Indication bzw. nach der Auswertung werden Überwachungs- und Alive-Zähler zurückgesetzt (blauer Pfeil nach oben).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerfall (SC 4 bis SC 5)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die erwartete Alive Indication bleibt aus (rot gestrichelter Balken).</li>\n<li>Beim Prüfzeitpunkt an SC 5 ergibt die Formel:</li>\n<li><code>CYCLE 5</code>: $n(AI) - n(SC) + EAI = 0 - 2 + 1 = -1 \\rightarrow$ <strong>not o.k.</strong></li>\n<li>Der Zustand wechselt zu <code>corrupted aliveness</code>.</li>\n<li>Ein Zähler-Reset erfolgt bedingt durch die erkannte Korruption (<code>caused by detected corruption</code>, roter Pfeil nach oben).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erholung (SC 6 bis SC 7)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Erreichen von SC 7 wird mit angepassten Zählerwerten geprüft:</li>\n<li><code>CYCLE 7</code>: $n(AI) - n(SC) + EAI = 0 - 1 + 1 = 0 \\rightarrow$ <strong>o.k.</strong></li>\n<li>Der Überwachungsstatus geht über <code>recovering aliveness</code> zurück in <code>continuous aliveness</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Algorithmus-Validierung</strong>: Das Szenario demonstriert eine Variante des Alive-Supervision-Algorithmus mit Zähler-Reset bei Alive-Indikation und bei erkannter Abweichung.</li>\n<li><strong>Toleranzgrenzen</strong>: Da <code>MinMargin = MaxMargin = 0</code>, führt jede Abweichung vom Ergebnis 0 unmittelbar zur Bewertung <code>not o.k.</code>.</li>\n<li><strong>EAI-Kompensation</strong>: Der Term <code>EAI = expected n(SC) - 1</code> dient als mathematischer Ausgleich für die Phasenverschiebung zwischen diskreten Überwachungszyklen und asynchronen Alive-Ereignissen.</li>\n</ul>"}], "trans": [{"from": "FIG-07a2ea8ce593aa52", "to": "FIG-15041c8a42ebc98c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
